-- === STEP 1: Delete SEO content ===
DELETE FROM category_seo_content
WHERE category_id IN (
  SELECT id FROM (
    SELECT id FROM categories WHERE parent_id IN (
      SELECT id FROM categories WHERE parent_id = (SELECT id FROM categories WHERE slug = 'local-business' AND level = 1)
    )
    UNION
    SELECT id FROM categories WHERE parent_id = (SELECT id FROM categories WHERE slug = 'local-business' AND level = 1)
  ) AS ids
);

-- === STEP 2: Nullify submission category_id ===
UPDATE submissions SET category_id = NULL
WHERE category_id IN (
  SELECT id FROM (
    SELECT id FROM categories WHERE parent_id IN (
      SELECT id FROM categories WHERE parent_id = (SELECT id FROM categories WHERE slug = 'local-business' AND level = 1)
    )
    UNION
    SELECT id FROM categories WHERE parent_id = (SELECT id FROM categories WHERE slug = 'local-business' AND level = 1)
  ) AS ids
);

